effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     #define pi 3.14159

     #define thc(a,b) tan(a*cos(b))/tan(a)
     #define ths(a,b) tan(a*sin(b))/tan(a)
     #define sabs(x) sqrt(x*x+1e-2)
     //#define sabs(x, k) sqrt(x*x+k)-0.1

     #define Rot(a) mat2(cos(a), -sin(a), sin(a), cos(a))

     float cc(float a, float b) {
         float f = thc(a, b);
         return sign(f) * pow(abs(f), 0.25);
     }

     float cs(float a, float b) {
         float f = ths(a, b);
         return sign(f) * pow(abs(f), 0.25);
     }

     vec3 pal(in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d) {
         return a + b*cos( 6.28318*(c*t+d) );
     }

     float h21(vec2 a) {
         return fract(sin(dot(a.xy, vec2(12.9898, 78.233))) * 43758.5453123);
     }

     float mlength(vec2 uv) {
         return max(abs(uv.x), abs(uv.y));
     }

     float mlength(vec3 uv) {
         return max(max(abs(uv.x), abs(uv.y)), abs(uv.z));
     }

     float smin(float a, float b) {
         float k = 0.12;
         float h = clamp(0.5 + 0.5 * (b-a) / k, 0.0, 1.0);
         return mix(b, a, h) - k * h * (1.0 - h);
     }

     float h21 (vec2 uv, float sc) {
         uv = mod(uv, sc);
         return fract(sin(dot(uv, vec2(12.9898, 78.233)))*43758.5453123);
     }

     float line(vec2 uv, float width) {
         return max(-uv.y + width, abs(uv.x));
     }

     float curve(vec2 uv) {
         return abs(length(uv-0.5) - 0.5);
     }

     float shape(vec2 uv, vec4 h, float width) {
         if (h.x + h.y + h.z + h.w == 0.)
             return 0.;

         // center circle to round off line segments
         float d = length(uv);     

         // draw line segment from center to edge (-width offset for center circle)
         d = mix(d, min(d, line(uv,     width)), h.x);
         d = mix(d, min(d, line(uv.yx,  width)), h.y);
         d = mix(d, min(d, line(-uv,    width)), h.z);
         d = mix(d, min(d, line(-uv.yx, width)), h.w);

         // draw quarter circle between 2 edges
         d = mix(d, min(d, curve(vec2(uv.x, uv.y))),   h.x * h.y);
         d = mix(d, min(d, curve(vec2(uv.x, -uv.y))),  h.y * h.z);
         d = mix(d, min(d, curve(vec2(-uv.x, -uv.y))), h.z * h.w);
         d = mix(d, min(d, curve(vec2(-uv.x, uv.y))),  h.w * h.x);

         float k = 6./acScreenSize.y;
         return smoothstep(-k, k, -d + width);
     }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     // umefx = acScreenNorm; 
     umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     umefx.y*=acLayerSize.y/acLayerSize.x;

     umefx /= scale;
     umefx *= rot2m((0.0+angle)*0.0174533);
     umefx += vec2((0.0-position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

         vec2 uv = umefx;
         // float width = 0.25;
         // float threshold = 0.5;  

         float sc = 18.0;

         uv.x += 10.0 + 0.1 * iTime;    

         vec2 ipos = floor(sc * uv) + xstep;
         vec2 fpos = fract(sc * uv) - 0.5;

         // arbitrary values - hash repetition, offset
         float rep = 302.; 
         float val = arby;   

         float s = 0.0;
         if (mod(ipos.x + ipos.y, 2.) == 0.) {
             vec4 h = vec4(h21(ipos,            rep),  // up
                           h21(ipos + val,      rep),  // right
                           h21(ipos + 2. * val, rep),  // down
                           h21(ipos + 3. * val, rep)); // left ( I think* )
             h = step(h, vec4(threshold));
             s = shape(fpos, h, width);
         } else {
             vec4 h = vec4(h21(ipos + vec2(0,1) + 2. * val, rep),  // up's down
                           h21(ipos + vec2(1,0) + 3. * val, rep),  // right's left
                           h21(ipos - vec2(0,1),            rep),  // down's up
                           h21(ipos - vec2(1,0) + val,      rep)); // left's right
             h = step(h, vec4(threshold));
             s = shape(fpos, h, width);        
         }

         // vec3 e = vec3(1);
         // vec3 col = s * pal(0.63 + 0.2 * uv.y, e, e, e, 0.15 * vec3(0,1,2)/3.);
         // col += (1.-s) * pal(0.57 + 0.23 * uv.y, e, e, e, 0.15 * vec3(0,1,2)/3.);
         vec3 col = vec3(s,s,s);

         fragColor = vec4(col,1.0);

 	    vec4 factor;
 	     // = mix(texColorX,fragColor,1.0);
 	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         float luminance = dot(fragColor.rgb, luminanceWeighting);
         vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    // if(GRADMAP) { 
 	    factor = mix(texColorX,gradmap,1.0); 
 	    // }

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
